(* [comment removed for export] *)
Lemma put_jt : forall m, mem_inv usegs m -> ro_cells usegs m PUT_JT PUT_JT_CELLS.
Proof.
  intros m MI.
  assert (L : length (cells_bytes PUT_JT_CELLS) = 48%nat) by (vm_compute; reflexivity).
  pose proof (ro_cells_image usegs m PUT_JT (cells_bytes PUT_JT_CELLS) MI
    ltac:(vm_compute; reflexivity) ltac:(unfold PUT_JT; lia) ltac:(rewrite L; unfold PUT_JT; lia)) as R.
  apply (ro_cells_reshape _ _ _ _ _ R); vm_compute; [tauto | reflexivity].
Qed.

(* [comment removed for export] *)
Definition put_frame (m : mem) (sp : word) (j8 : list byte) (tmp : list cell) (p : Z) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -144) [CB 8 j8]
  /\ rw_cells usegs m (bv_unsigned sp + -136) tmp /\ cells_size tmp = 24%nat
  /\ rw_cells usegs m (bv_unsigned sp + -112) [C8 (wz p)].
