(* [comment removed for export] *)
Definition put_common_post (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (rax t0 t1 t2 : word) (E p0 : Z) (a3 a4 a5 a6 a7 : word) (P p1 : Z) (t3 t4 t5 t6 : word) (c : pcore) (p : Z) (E1 : ecv) (m : mem)
    : machine_state -> Prop :=
  fun ms' => put_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo (p - p0) m ms'
          \/ (exists a1 a2, ms' = put_disp_ms rax sp gp tp t0 t1 t2 E p0 (pc_state c) a1 a2 p a3 a4 a5 a6 a7 P p1 t3 t4 t5 t6 F fc m
                 /\ p < p1 /\ pc_state c <> 11 /\ Z.testbit (pc_f c) 1 = true /\ ec_failed E1 = false).

Definition put_common_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 j8 : list byte) (tmp : list cell) (p p0 p1 : Z) (E1 : ecv),
  put_frame m sp j8 tmp p ->
  rw_cells usegs m (bv_unsigned sp + -104) (map C8 (put_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells usegs m E (ErrCodeCells E1) -> ec_ok E1 ->
  stk usegs m lo (bv_unsigned sp + -144) -> 0 <= lo -> lo <= bv_unsigned sp + -144 ->
  0 <= p0 -> p0 <= p -> p <= p1 -> p1 < 2^64 -> 0 <= P -> P + 80 <= 2^64 -> 0 <= E -> E + 24 <= 2^64 ->
  evt usegs (put_common_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo rax t0 t1 t2 E p0 a3 a4 a5 a6 a7 P p1 t3 t4 t5 t6 c p E1 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) a0 a1 a2 a3 a4 a5 a6 a7
              (wz P) s3x (wz p1) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
        F (Z_to_bv 64 PUT_COMMON) fc None m (seg_rom usegs)).

