  put_frame m sp j8 tmp p ->
  rw_cells usegs m (bv_unsigned sp + -104) (map C8 (put_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells usegs m E (ErrCodeCells EC_clear) ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp + -144) -> lo + 176 <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  0 <= p0 -> p0 <= p -> p <= p1 -> p1 < 2^64 ->
