        (p1 = p /\ put_nm_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo P E c pad7 pad2 m ms')
     \/ (p < p1 /\ exists m', ms' = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) (wz (put_target 0)) a1 a2 a3 a4 a5 a6 a7
                                            (wz P) (wz (p1 - p)) (wz p1) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
                                       F (Z_to_bv 64 (put_target 1)) fc None m' (seg_rom usegs)
            /\ munch [(P, P + 80)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
            /\ rw_cells usegs m' P (ParserCoreCells (pc_set_state c 1) pad7 pad2)))
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) (wz (put_target 0)) a1 a2 a3 a4 a5 a6 a7
              (wz P) (wz (p1 - p)) (wz p1) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
