Definition put_entry_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 ej : list byte) (p0 n : Z),
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> pc_state c <> 11 ->
  rw_cells usegs m E [CB 24 ej] ->
  stk usegs m lo (bv_unsigned sp) -> lo + 144 <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  0 <= p0 -> 0 <= n -> p0 + n < 2^64 ->
  0 < p0 ->                                                   (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (fun ms' => exists a1 a2 m' j8 jt,
        ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) (wz (pc_state c)) a1 a2 (wz E) a4 a5 a6 a7
                      (wz P) (wz n) (wz (p0 + n)) (wz 11) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
                 F (Z_to_bv 64 PUT_DISP) fc None m' (seg_rom usegs)
        /\ munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
        /\ stk usegs m' lo (bv_unsigned sp + -144)
        /\ put_frame m' sp j8 [CB 24 jt] p0
        /\ rw_cells usegs m' (bv_unsigned sp + -104) (map C8 (put_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
        /\ rw_cells usegs m' P (ParserCoreCells c pad7 pad2)
        /\ rw_cells usegs m' E (ErrCodeCells EC_clear))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz p0) (wz n) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PUT) fc None m (seg_rom usegs)).

